  values (v_ver, v_l1, $academy_seed$q01$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Expliquer le revenu et les frais d'une SCPI$academy_seed$, $academy_seed$Cas fictif. Un client lit « taux de distribution 4,8 % » sur la fiche d'une SCPI. Quelle formulation pouvez-vous employer en rendez-vous ?$academy_seed$, $academy_seed$["« Vous toucherez 4,8 % par an sur votre capital. »","« C'est ce que la SCPI a distribué l'an dernier, rapporté au prix de part ; cela peut baisser et c'est avant impôt. »","« C'est le rendement garanti par la société de gestion sur la durée recommandée. »","« C'est le rendement net de tous frais et de toute fiscalité. »"]$academy_seed$::jsonb, 1)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Le taux de distribution est une observation passée, calculée sur un prix de part qui peut varier, brute d'impôt et de prélèvements sociaux. Les loyers peuvent diminuer et le capital n'est pas garanti. La leçon 1 rappelle que ce chiffre n'est jamais une promesse.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q02$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Expliquer le revenu et les frais d'une SCPI$academy_seed$, $academy_seed$Cas fictif. Une cliente souscrit 40 000 € de parts d'une SCPI dont le DIC indique une commission de souscription de 9 %. Que lui dites-vous sur la valeur de retrait le lendemain, avant toute variation de marché ?$academy_seed$, $academy_seed$["Elle est égale à 40 000 €, la commission est prélevée sur les loyers futurs.","Elle est inférieure à 40 000 €, d'environ 3 600 €, car la commission est intégrée au prix de la part.","Elle est supérieure à 40 000 € grâce au délai de jouissance.","Elle est impossible à estimer tant que la société de gestion n'a pas publié le rapport annuel."]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$La commission de souscription est intégrée au prix de souscription et revient à la société de gestion (la note d'information détaille ce qu'elle couvre). La valeur de retrait, dès le lendemain, en est diminuée d'autant. La leçon 1 explique que cette commission rend le placement long, plusieurs années de loyers étant nécessaires pour la compenser.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q03$academy_seed$, $academy_seed$vrai_faux$academy_seed$, $academy_seed$Expliquer le revenu et les frais d'une SCPI$academy_seed$, $academy_seed$Vrai ou faux. « Rendement sans la gestion » signifie que l'associé d'une SCPI ne supporte aucun frais de gestion.$academy_seed$, $academy_seed$["Vrai","Faux"]$academy_seed$::jsonb, 1)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$La formule signifie que l'associé ne gère pas lui-même les immeubles. La société de gestion se rémunère par une commission de gestion prélevée sur les loyers, généralement entre 8 % et 10 % des revenus selon l'AMF. La leçon 1 invite à montrer cette ligne dans le DIC.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l2, $academy_seed$q04$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Expliquer la liquidité et le délai de sortie d'une SCPI$academy_seed$, $academy_seed$Cas fictif. Un client détient des parts d'une SCPI à capital variable et veut récupérer 30 000 € dans deux mois. Quelle affirmation est exacte ?$academy_seed$, $academy_seed$["La société de gestion est tenue de racheter les parts dans un délai réglementaire d'un mois.","Le retrait dépend des souscriptions reçues en face ; il n'a pas de date garantie et peut attendre plusieurs mois.","Une demande de retrait complète est exécutée sous trois semaines.","Le retrait est immédiat si les parts ont été financées à crédit."]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Dans une SCPI à capital variable, le prix de retrait est fixé par la société de gestion mais l'exécution dépend des demandes de souscription reçues. Le médiateur de l'AMF a traité le cas d'une demande complète non exécutée pendant au moins six mois. La leçon 2 demande d'annoncer ce délai incertain avant toute souscription.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l2, $academy_seed$q05$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Expliquer la liquidité et le délai de sortie d'une SCPI$academy_seed$, $academy_seed$Cas fictif. Un client hésite entre une SCPI à capital fixe et une SCPI à capital variable et vous demande comment se forme le prix de revente dans une SCPI à capital fixe. Que répondez-vous ?$academy_seed$, $academy_seed$["Il est fixé par la société de gestion, indépendamment de l'offre et de la demande.","Il se forme par confrontation des ordres d'achat et de vente sur un marché secondaire, avec une périodicité d'un jour à trois mois, et peut s'écarter de la valeur du patrimoine.","Il est égal à la dernière valeur d'expertise des immeubles.","Il reste figé au prix de souscription d'origine."]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Le guide AMF précise qu'en capital fixe, le vendeur inscrit un ordre avec un prix minimum et que le prix résulte de la confrontation de l'offre et de la demande, selon une périodicité de 1 jour à 3 mois. C'est en capital variable que le prix de retrait est défini par la société de gestion. La leçon 2 distingue ces deux mécanismes.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l2, $academy_seed$q06$academy_seed$, $academy_seed$vrai_faux$academy_seed$, $academy_seed$Expliquer la liquidité et le délai de sortie d'une SCPI$academy_seed$, $academy_seed$Vrai ou faux. Une demande de retrait de parts de SCPI complète et enregistrée par la société de gestion garantit son exécution en quelques semaines.$academy_seed$, $academy_seed$["Vrai","Faux"]$academy_seed$::jsonb, 1)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Le médiateur de l'AMF a rappelé qu'une demande en bonne et due forme est nécessaire mais pas suffisante : sans souscriptions en face, l'exécution peut attendre plusieurs mois. La leçon 2 en tire la règle : n'orienter vers la SCPI que l'argent dont le client n'aura pas besoin avant des années.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l3, $academy_seed$q07$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Nommer les risques et la fiscalité à vérifier d'une SCPI$academy_seed$, $academy_seed$Cas fictif. Un client ne détient aucun immeuble loué en direct, seulement des parts de SCPI qui lui procurent 6 000 € de revenus fonciers par an. Quel régime déclaratif lui indiquez-vous ?$academy_seed$, $academy_seed$["Le micro-foncier avec abattement de 30 %, puisqu'il reste sous 15 000 €.","Le régime réel : le détenteur de parts seules est expressément exclu du micro-foncier.","Le prélèvement forfaitaire unique, comme pour un dividende d'action.","Aucune déclaration, les revenus étant déjà imposés au niveau de la SCPI."]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Selon impots.gouv.fr et le BOFIP (BOI-RFPI-DECLA-10), les contribuables qui ne détiennent que des parts de sociétés immobilières sont exclus du micro-foncier ; ils déclarent leur quote-part au réel. La leçon 3 précise que le seuil de 15 000 € et l'abattement de 30 % ne concernent que le contribuable qui loue aussi un immeuble nu en direct.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l3, $academy_seed$q08$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Nommer les risques et la fiscalité à vérifier d'une SCPI$academy_seed$, $academy_seed$Cas fictif. Un client vous demande ce qu'il paiera, en plus de l'impôt sur le revenu, sur les revenus fonciers distribués par sa SCPI. Que répondez-vous, source officielle à l'appui ?$academy_seed$, $academy_seed$["Des prélèvements sociaux au taux global de 17,2 %, appliqués au revenu net.","Rien, les revenus fonciers imposés au barème sont exonérés de prélèvements sociaux.","Des prélèvements sociaux de 12,8 % comme sur les dividendes.","Rien tant que les parts ne sont pas cédées."]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 0, $academy_seed$La page impots.gouv.fr consultée le 21 septembre 2026 fixe le taux global des prélèvements sociaux sur les revenus fonciers à 17,2 % (CSG 9,2 %, CRDS 0,5 %, prélèvement de solidarité 7,5 %), sur le revenu net. La leçon 3 recommande de montrer cette page à l'écran plutôt que de réciter un chiffre.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l3, $academy_seed$q09$academy_seed$, $academy_seed$cas_court$academy_seed$, $academy_seed$Nommer les risques et la fiscalité à vérifier d'une SCPI$academy_seed$, $academy_seed$Cas fictif. Un dirigeant souhaite financer 150 000 € de parts de SCPI par un emprunt sur quinze ans, « puisque les loyers rembourseront les mensualités ». Quel risque nommez-vous en priorité ?$academy_seed$, $academy_seed$["Aucun risque particulier : les loyers couvrent les mensualités par construction.","Les mensualités sont certaines alors que les loyers et la valeur de revente ne le sont pas ; en cas de baisse, le client complète de sa poche et ne peut pas sortir vite.","Le seul risque est fiscal, les intérêts n'étant pas déductibles.","Le risque de liquidité disparaît puisque la banque prend les parts en garantie."]$academy_seed$::jsonb, 3)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$L'AMF rappelle que le capital n'est pas garanti et que les revenus locatifs peuvent diminuer. La leçon 3 nomme le risque de crédit : mensualités certaines, loyers incertains, sortie soumise au délai de retrait. Le crédit ne supprime aucun des trois autres risques, il les cumule.$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l1, $academy_seed$q10$academy_seed$, $academy_seed$cas_court$academy_seed$, $academy_seed$Expliquer le revenu et les frais d'une SCPI$academy_seed$, $academy_seed$Cas fictif. Un client vous dit : « Pourquoi payer 10 % à l'entrée alors qu'un livret ne coûte rien ? » Quelle réponse correspond à la posture du cabinet ?$academy_seed$, $academy_seed$["Minimiser : « 10 %, c'est la norme du marché, on ne le voit plus au bout d'un an. »","Expliquer que la commission revient à la société de gestion (la note d'information détaille ce qu'elle couvre), qu'elle rend le placement long, montrer la ligne dans le DIC et vérifier avec lui que son horizon justifie ce placement.","Lui promettre une SCPI sans frais d'entrée sans avoir ouvert son DIC.","Répondre que la commission est déductible de son impôt sur le revenu."]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$La leçon 1 demande de nommer les frais, de les montrer dans le DIC et de relier le placement à l'horizon du client. Une commission de souscription de 5 % à 12 % selon l'AMF ne se justifie que par une détention longue. Les autres réponses minimisent, promettent sans document ou avancent une règle fiscale non vérifiée.$academy_seed$);
